#!/usr/bin/env python3
"""Turn a GitHub Issue Form submission into a change in data/*.json.

Used by .github/workflows/issue-to-data.yml. Handles the "add" forms
(data:speaking, data:project, data:testimonial) and the "update or remove"
forms (data:edit), which are generated by build_manage.py. The Content Studio
(studio.html) opens issues with the same "### Label" body, so they're read the same way.
Reads the issue from env vars (never shell-interpolated) and writes:
  - the updated data file, plus any uploaded files saved under assets/events/ (event_files.py)
  - $RESULT_FILE: a markdown message to post back on the issue
  - $GITHUB_OUTPUT: file=<data file>, message=<commit message>

Exit code 0 = change applied, 1 = validation failed (message explains why).

Local test:
  ISSUE_LABELS='["data:speaking"]' ISSUE_BODY="$(cat body.md)" RESULT_FILE=/dev/stdout \
    python3 .github/scripts/issue_to_data.py
"""
import difflib
import json
import os
import re
import sys
from datetime import datetime
from pathlib import Path

from event_files import local_path, local_paths, organize, prune

ROOT = Path(__file__).resolve().parents[2]
SITE = "https://nomadicmehul.dev"
ROLES = [r["name"] for r in json.loads((ROOT / "data" / "roles.json").read_text())]
# (add-form label, resource type, button label) — order matches the speaking card buttons
RESOURCE_FIELDS = [
    ("Event page URL", "event", "Event Page"),
    ("Slides", "slides", "Slide Deck"),
    ("Code repo URL", "code", "GitHub Repo"),
    ("Live demo URL", "demo", "Live Demo"),
    ("Recording URL", "video", "Recording"),
    ("Blog post URL", "blog", "Blog Post"),
]
RESOURCE_LABELS = {rtype: button for _, rtype, button in RESOURCE_FIELDS}
DATE_FORMATS = ("%Y-%m-%d", "%Y/%m/%d", "%d.%m.%Y", "%d %b %Y", "%d %B %Y", "%b %d %Y", "%B %d %Y")


# ---------- form parsing ----------

def parse_form(body):
    """Split an issue-form body ('### Label\\n\\nvalue' blocks) into {label: value}."""
    fields = {}
    body = re.sub(r"<!--.*?-->", "", body or "", flags=re.S)  # hints like "drop the file here"
    for block in re.split(r"^### ", body, flags=re.M)[1:]:
        label, _, value = block.partition("\n")
        value = value.strip()
        fields[label.strip()] = "" if value == "_No response_" else value
    return fields


def checked(value):
    return re.findall(r"^- \[[xX]\] (.+)$", value, flags=re.M)


def csv(value):
    return [v.strip() for v in value.split(",") if v.strip()]


def is_url(value):
    return re.match(r"^https?://\S+$", value) is not None


def form_url(value):
    """A URL from a form field; files dragged into a textarea arrive as [name](url)."""
    link = re.search(r"\]\((https?://[^)\s]+)\)", value)
    return link.group(1) if link else value.strip()


def parse_date(value):
    """YYYY-MM-DD, or a written-out date: 22 Oct 2026, Oct 22nd, 2026, 22.10.2026, 2026/10/22."""
    s = " ".join(re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", value.replace(",", " ")).split())
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    return None


# ---------- validation (shared by add and edit) ----------

def validate_speaking(e, errors):
    day = parse_date(e.get("date", ""))
    if day:
        e["date"], e["year"] = day.isoformat(), day.year
    else:
        errors.append(f"**date** must be a date like `2026-06-09` or `9 Jun 2026` (got `{e.get('date', '')}`)")
    for key in ("title", "location"):
        if not e.get(key):
            errors.append(f"**{key}** is required")
    if not e.get("topics"):
        errors.append("**topics** needs at least one topic")
    roles = e.get("role", [])
    unknown = [r for r in ([roles] if isinstance(roles, str) else roles) if r not in ROLES]
    if unknown:
        errors.append(f"Unknown role {unknown} — use: {', '.join(ROLES)}")
    for r in e.get("resources", []):
        if r["type"] not in RESOURCE_LABELS:
            errors.append(f"Unknown resource type `{r['type']}` — use: {', '.join(RESOURCE_LABELS)}")
        elif not r["url"]:
            errors.append(f"**{r['type']}**: no link or file — paste a URL or drag the file in after `{r['type']} |`")
        elif is_url(r["url"]):
            continue
        elif re.match(r"^\w+:", r["url"]) or " " in r["url"].strip():
            errors.append(f"**{r['type']}** link must start with `http://` or `https://` (got `{r['url']}`)")
        elif not (ROOT / local_path(r["url"])).is_file():
            # a file already on the site: bare names live in assets/slides/, paths start at the site root
            errors.append(f"**{r['type']}**: `{local_path(r['url'])}` doesn't exist — drag the file into the issue or paste a full URL")


def validate_project(e, errors):
    for key in ("title", "description"):
        if not e.get(key):
            errors.append(f"**{key}** is required")
    if not e.get("repo", "").startswith("https://github.com/"):
        errors.append("**repo** must start with `https://github.com/`")
    if not e.get("tech"):
        errors.append("**tech** needs at least one entry")
    if not re.match(r"^#[0-9a-fA-F]{3,8}$", e.get("iconColor", "")):
        errors.append(f"**iconColor** must be a hex color like `#4ade80` (got `{e.get('iconColor', '')}`)")


def validate_testimonial(e, errors):
    for key in ("quote", "name", "role"):
        if not e.get(key):
            errors.append(f"**{key}** is required")
    if not 1 <= e.get("stars", 0) <= 5:
        errors.append("**stars** must be 1–5")
    if e.get("link") and not is_url(e["link"]):
        errors.append("**link** must start with `http://` or `https://`")


# ---------- add forms ----------

def build_speaking(f):
    resources = [
        {"type": rtype, "label": button, "url": form_url(f[label])}
        for label, rtype, button in RESOURCE_FIELDS if f.get(label)
    ]
    return {
        "year": None,  # filled in from date by validate_speaking
        "date": f.get("Date", ""),
        "title": f.get("Event title", ""),
        "location": f.get("Location", ""),
        "role": checked(f.get("Role", "")) or ["Speaker"],
        "topics": csv(f.get("Topics", "")),
        "resources": resources,
    }


def build_project(f):
    return {
        "title": f.get("Project title", ""),
        "description": f.get("Description", ""),
        "icon": f.get("Icon", "") or "fas fa-code",
        "iconColor": f.get("Icon color", "") or "#4ade80",
        "repo": f.get("GitHub repo URL", ""),
        "tech": csv(f.get("Tech", "")),
        "featured": bool(checked(f.get("Featured", ""))),
    }


def build_testimonial(f):
    return {
        "quote": f.get("Quote", ""),
        "name": f.get("Name", ""),
        "role": f.get("Role", ""),
        "stars": int(f.get("Stars") or 5),
        "link": f.get("Link", ""),
    }


# Edit-form inputs: (form label, entry key, widget, help). Blank = keep the current value.
# Widgets: text, textarea, list (comma-separated), roles (checkboxes), bool (Keep/Yes/No), stars (Keep/5..1).
# build_manage.py renders these; edit() below reads them back.
TYPES = {
    "speaking": {
        "path": "data/speaking.json", "noun": "speaking event", "key": "title",
        "build": build_speaking, "validate": validate_speaking,
        "edit_inputs": [
            ("New title", "title", "text", ""),
            ("New date", "date", "text", "YYYY-MM-DD or e.g. 9 Jun 2026 — files move to the event's new folder"),
            ("New location", "location", "text", "City, Country"),
            ("New roles", "role", "roles", "Tick to replace the current roles; leave all unticked to keep them"),
            ("New topics", "topics", "list", "Comma-separated; replaces the current topics"),
        ],
    },
    "project": {
        "path": "data/projects.json", "noun": "project", "key": "title",
        "build": build_project, "validate": validate_project,
        "edit_inputs": [
            ("New title", "title", "text", ""),
            ("New description", "description", "textarea", ""),
            ("New repo URL", "repo", "text", "https://github.com/..."),
            ("New tech", "tech", "list", "Comma-separated; replaces the current list"),
            ("New icon", "icon", "text", "FontAwesome 6 class, e.g. fas fa-cloud"),
            ("New icon color", "iconColor", "text", "Hex color, e.g. #4ade80"),
            ("Featured", "featured", "bool", "Show on the home page"),
        ],
    },
    "testimonial": {
        "path": "data/testimonials.json", "noun": "testimonial", "key": "name",
        "build": build_testimonial, "validate": validate_testimonial,
        "edit_inputs": [
            ("New quote", "quote", "textarea", ""),
            ("New name", "name", "text", ""),
            ("New role", "role", "text", ""),
            ("Stars", "stars", "stars", ""),
            ("New link", "link", "text", "Full URL, or `-` to remove the link"),
        ],
    },
}
ADD_LABELS = {"data:speaking": "speaking", "data:project": "project", "data:testimonial": "testimonial"}
# entry field label in each generated update form → data type
EDIT_FIELDS = {"Speaking event": "speaking", "Project": "project", "Testimonial": "testimonial"}


def entry_labels(kind, data):
    """Display label for each entry, aligned with data (MANAGE.md links pre-fill it). Shared with build_manage.py."""
    if kind == "speaking":
        labels = [f"{e['title']} ({e.get('date', e.get('year'))})" for e in data]
    elif kind == "project":
        labels = [e["title"] for e in data]
    else:
        labels = [f"{e['name']} — {e['role']}" for e in data]
    seen = {}
    for i, label in enumerate(labels):  # labels must identify one entry
        seen[label] = seen.get(label, 0) + 1
        if seen[label] > 1:
            labels[i] = f"{label} #{seen[label]}"
    return labels


def add(kind, f, data, errors):
    t = TYPES[kind]
    entry = t["build"](f)
    if kind == "speaking":  # the Content Studio sends every link as "type | label | url" lines
        apply_resources(entry, f.get("Add resources", ""), "", errors)
    t["validate"](entry, errors)
    if kind == "speaking" and any(e.get("title") == entry["title"] and e.get("date") == entry["date"] for e in data):
        errors.append("An event with this title and date already exists")
    if kind == "project" and any(p.get("repo") == entry["repo"] for p in data):
        errors.append("A project with this repo already exists")
    if not errors:
        data.insert(0, entry)
    return "add", entry


# ---------- edit form ----------

def find_entry(kind, data, query, errors):
    """Exact label (as pre-filled from MANAGE.md), else exact title/name, else a unique partial match."""
    labels = entry_labels(kind, data)
    query = query.strip()
    if query in labels:
        return data[labels.index(query)]
    key, ql = TYPES[kind]["key"], query.lower()
    hits = [i for i, e in enumerate(data) if labels[i].lower() == ql or str(e.get(key, "")).lower() == ql] \
        or [i for i in range(len(data)) if ql and ql in labels[i].lower()]
    if len(hits) == 1:
        return data[hits[0]]
    if hits:
        errors.append(f"**{query}** matches {len(hits)} entries — use one of: " + ", ".join(f"`{labels[i]}`" for i in hits[:6]))
    else:
        close = difflib.get_close_matches(query, labels, n=3, cutoff=0.5)
        errors.append(f"**{query}** not found" + (f" — did you mean {', '.join(f'`{c}`' for c in close)}?" if close else "")
                      + f" — find it in [MANAGE.md](https://github.com/{os.environ.get('GITHUB_REPOSITORY', 'nomadicmehul/nomadicmehul.github.io')}/blob/main/MANAGE.md)")
    return None


def apply_inputs(entry, f, inputs):
    """Copy every filled-in edit input onto the entry; returns how many changed."""
    changed = 0
    for label, key, widget, _ in inputs:
        value = f.get(label, "")
        if widget == "roles":
            value = checked(value)
        if not value or value == "Keep":
            continue
        if widget in ("list", "roles"):
            entry[key] = value if widget == "roles" else csv(value)
        elif widget == "bool":
            entry[key] = value == "Yes"
        elif widget == "stars":
            entry[key] = int(value)
        else:
            entry[key] = "" if value == "-" else value
        changed += 1
    return changed


def apply_resources(entry, add_text, remove_text, errors):
    resources = entry.setdefault("resources", [])
    for rtype in csv(remove_text.lower()):
        if not any(r["type"] == rtype for r in resources):
            errors.append(f"No `{rtype}` resource to remove")
        resources[:] = [r for r in resources if r["type"] != rtype]
    pending = None  # the last "slides |" line still waiting for its file
    for line in add_text.splitlines():
        if not line.strip():
            continue
        parts = [p.strip() for p in line.split("|")]
        if len(parts) == 1 and pending and is_url(form_url(line)):  # file dropped on the next line
            pending["url"], pending = form_url(line), None
            continue
        if len(parts) == 4 and parts[2].startswith("["):  # a dragged-in file whose name has a "|"
            parts = parts[:2] + ["|".join(parts[2:])]
        if len(parts) not in (2, 3):
            errors.append(f"Can't read resource `{line.strip()}` — use `type | url` or `type | label | url`")
            continue
        rtype = parts[0].lower()
        label = parts[1] if len(parts) == 3 else RESOURCE_LABELS.get(rtype, rtype.title())
        resources.append({"type": rtype, "label": label, "url": form_url(parts[-1])})
        if not resources[-1]["url"]:
            pending = resources[-1]


def edit(kind, f, data, errors):
    t = TYPES[kind]
    field = next(label for label, k in EDIT_FIELDS.items() if k == kind)
    entry = find_entry(kind, data, f.get(field, ""), errors)
    if entry is None:
        return None, None
    if f.get("Action") == "Remove":
        data.remove(entry)
        return "remove", entry

    changed = apply_inputs(entry, f, t["edit_inputs"])
    add_res, remove_res = f.get("Add resources", ""), f.get("Remove resources", "")
    if kind == "speaking":
        apply_resources(entry, add_res, remove_res, errors)
    if not (changed or add_res or remove_res):
        errors.append("Nothing to update — fill in at least one field (blank fields are left unchanged)")
    t["validate"](entry, errors)
    return "update", entry


# ---------- main ----------

def main():
    labels = json.loads(os.environ.get("ISSUE_LABELS", "[]"))
    result = Path(os.environ["RESULT_FILE"])
    f = parse_form(os.environ.get("ISSUE_BODY", ""))

    if "data:edit" in labels:
        kind = next((k for label, k in EDIT_FIELDS.items() if f.get(label)), None)
        handler = edit
    else:
        kind = next((ADD_LABELS[l] for l in labels if l in ADD_LABELS), None)
        handler = add
    if not kind:
        result.write_text("Couldn't tell which data file this issue is for — nothing to do.")
        return 1

    t = TYPES[kind]
    path = ROOT / t["path"]
    data = json.loads(path.read_text())
    errors, saved = [], []
    before = [p for e in data for p in local_paths(e)] if kind == "speaking" else []
    action, entry = handler(kind, f, data, errors)
    if kind == "speaking" and action in ("add", "update") and not errors:
        saved = organize(entry, errors)  # uploads → assets/events/<year>/<date>-<title>/

    if errors:
        result.write_text(
            f"❌ Couldn't {action or 'change'} this {t['noun']}:\n\n" + "\n".join(f"- {e}" for e in errors)
            + "\n\nEdit the issue to fix it — the workflow re-runs automatically."
        )
        return 1

    if kind == "speaking":
        data.sort(key=lambda e: e.get("date", ""), reverse=True)  # newest first; stable for same-day events
        prune(before, data)  # files moved to a new folder, or of removed resources/events
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n")

    verb, prep = {"add": ("Added", "to"), "update": ("Updated", "in"), "remove": ("Removed", "from")}[action]
    name = " ".join(str(entry[t["key"]]).split())  # one line: it goes into $GITHUB_OUTPUT and the commit message
    with open(os.environ.get("GITHUB_OUTPUT", os.devnull), "a") as out:
        out.write(f"file={t['path']}\nmessage=data: {action} {t['noun']} \"{name}\"\n")
    page = {"speaking": "speaking.html", "project": "projects.html", "testimonial": "index.html#testimonials"}[kind]
    files = "".join(f"- [`{p}`]({SITE}/{p})\n" for p in saved)
    result.write_text(
        f"✅ {verb} {t['noun']} **{name}** {prep} `{t['path']}`. The site redeploys in a minute or two: [view it live]({SITE}/{page}).\n\n"
        + (f"📁 Saved to the site (opens in the browser, not as a download):\n{files}\n" if files else "")
        + f"<details><summary>Entry as saved</summary>\n\n```json\n{json.dumps(entry, indent=2, ensure_ascii=False)}\n```\n</details>\n\n"
        f"Manage everything in the [Content Studio]({SITE}/studio.html) or [MANAGE.md](https://github.com/{os.environ.get('GITHUB_REPOSITORY', 'nomadicmehul/nomadicmehul.github.io')}/blob/main/MANAGE.md)."
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
